from scipy.stats import chi2_contingency

def process(contingency_table):
    ct = contingency_table.set_index('region')[['H', 'L', 'N']]
    chi2, p_value, dof, expected = chi2_contingency(ct.values)
    result_df = pd.DataFrame({
        'statistic': [chi2],
        'p_value': [p_value]
    })
    return result_df

def process(chi_square_test) -> pd.DataFrame:
    result = chi_square_test.iloc[0]
    stat = round(result['statistic'], 3)
    pval = round(result['p_value'], 3)
    return pd.DataFrame({'statistic': [stat], 'p_value': [pval]})

